SELECT sampled_at AS ts, metric, SUM(sample_value) AS agg
  FROM metrics_samples
 WHERE resolution = #{resolution}
   AND sampled_at >= #{from}
   AND metric IN
   #{m}
   AND metric_name = #{name}
 GROUP BY sampled_at, metric
 ORDER BY sampled_at

SELECT * FROM metrics_samples
 WHERE resolution = 'MIN' AND metric = 'RESOURCE' AND sampled_at >= #{from}
 ORDER BY sampled_at
